"""Test block EditForm (Data): The form that creates a record or edits one: labelled fields, help under them, errors that say how to fix them, and one Save button.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/data/EditForm.md and its markup
(kit/blocks/data/EditForm.html; source b898c341fd76), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  When I fill {field} with {text}
  When I choose {option} for {field}
  When I pick {option}
  When I save
  When I cancel
  Then the field {field} has {text}
  Then the field {field} shows the error {text}
  Then the field {field} says {text}
  Then the option {option} is picked
  Then the form is in the {state} state
States (from the card): New, Edit, Field error, Several errors, Saving, Saved, Server error, Changed elsewhere,
Leaving with changes, Error texts with numbers. Checked by the state step: Field error, Saving.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "EditForm"
ROUTE = "/notes/new"
STATES = ["New", "Edit", "Field error", "Several errors", "Saving", "Saved", "Server error", "Changed elsewhere", "Leaving with changes", "Error texts with numbers"]
DEFAULT_STATE = "New"
CHECKED_STATES = ["Field error", "Saving"]
DEMO = ["kit/blocks/data/EditForm.html"]
SELF_TEST = [
    "Then the field \"Title\" has \"Week 3 · Vocabulary\"",
    "Then the field \"Title\" says \"Up to 120 characters\"",
    "When I fill \"Title\" with \"Week 4\"",
    "Then the field \"Title\" has \"Week 4\"",
    "When I choose \"Grammar\" for \"Subject\"",
    "Then the field \"Subject\" has \"grammar\"",
    "When I pick \"My class\"",
    "Then the option \"My class\" is picked",
    "When I save",
    "Then the field \"Title\" has \"Week 3 · Vocabulary\"",
]

steps = Registry(block=BLOCK)


class EditForm:
    """The EditForm block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def field(self, field):
        return p.control(self.page, label=str(field), block=BLOCK)

    def choice(self, option):
        return p.control(self.page, role="radio", name=str(option), block=BLOCK)

    def save(self):
        return p.control(self.page, role="button", name="Save", block=BLOCK)

    def cancel(self):
        return p.control(self.page, role="link", name="Cancel", block=BLOCK)

    def invalid(self):
        return p.control(self.page, css="[aria-invalid=\"true\"]", block=BLOCK)

    def expect_state(self, state: str) -> None:
        """Check one of the card's states: Field error, Saving."""
        b = self
        if state == "Field error":
            p.expect_visible(b.invalid().first)
        elif state == "Saving":
            p.expect_attribute(b.save(), "aria-busy", "true")
        else:
            raise AssertionError(f"EditForm has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("When I fill {field} with {text}", level="e2e")
def when_i_fill_field_with_text(world, field, text):
    b = EditForm(world.page, getattr(world, "base_url", ""))
    p.fill(b.field(field), str(text))


@steps.step("When I choose {option} for {field}", level="e2e")
def when_i_choose_option_for_field(world, option, field):
    b = EditForm(world.page, getattr(world, "base_url", ""))
    p.select(b.field(field), str(option))


@steps.step("When I pick {option}", level="e2e")
def when_i_pick_option(world, option):
    b = EditForm(world.page, getattr(world, "base_url", ""))
